import{_ as d,a0 as p,w as o,s as r,I as i,x as s,a1 as a,A as l,ao as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"5 個針對有經驗用户的 Vim 實用技巧 | LCTT x X-CMD","titleTemplate":false,"description":"5 個針對有經驗用户的 Vim 實用技巧 | LCTT (201701) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"5 個針對有經驗用户的 Vim 實用技巧 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"5 個針對有經驗用户的 Vim 實用技巧 | LCTT (201701) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201701/20140812 5 Vim Tips and Tricks for Experienced Users - part3","title":"5 個針對有經驗用户的 Vim 實用技巧","tag":"201701","desc":""},"relativePath":"201701/20140812 5 Vim Tips and Tricks for Experienced Users - part3.md","filePath":"[post].md"}'),m={name:"201701/20140812 5 Vim Tips and Tricks for Experienced Users - part3.md"};function c(h,e,k,g,u,f){const t=p("Link");return o(),r("div",null,[e[20]||(e[20]=i("h1",{id:"_5-個針對有經驗用户的-vim-實用技巧",tabindex:"-1"},[s("5 個針對有經驗用户的 Vim 實用技巧 "),i("a",{class:"header-anchor",href:"#_5-個針對有經驗用户的-vim-實用技巧","aria-label":"Permalink to “5 個針對有經驗用户的 Vim 實用技巧”"},"​")],-1)),e[21]||(e[21]=i("p",null,[i("img",{src:"https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-tips-tricks-featured.jpg",alt:"",title:"5 Vim Tips and Tricks for Experienced Userss"})],-1)),i("p",null,[e[1]||(e[1]=s("這篇文章是 ",-1)),a(t,{href:"https://www.maketecheasier.com/series/vim-user-guide/"},{default:l(()=>[...e[0]||(e[0]=[s("Vim 用户指南",-1)])]),_:1}),e[2]||(e[2]=s("系列文章中的一篇：",-1))]),i("ul",null,[i("li",null,[a(t,{href:"https://www.maketecheasier.com/start-with-vim-linux/"},{default:l(()=>[...e[3]||(e[3]=[s("Vim 初學者入門指南",-1)])]),_:1})]),i("li",null,[a(t,{href:"https://www.maketecheasier.com/vim-keyboard-shortcuts-cheatsheet/"},{default:l(()=>[...e[4]||(e[4]=[s("Vim 快捷鍵速查表",-1)])]),_:1})]),e[6]||(e[6]=i("li",null,"5 個針對有經驗用户的 Vim 實用技巧",-1)),i("li",null,[a(t,{href:"https://www.maketecheasier.com/vim-tips-tricks-advanced-users/"},{default:l(()=>[...e[5]||(e[5]=[s("3 個針對高級用户的 Vim 編輯器實用技巧",-1)])]),_:1})])]),e[22]||(e[22]=n('<p>Vim 編輯器提供了很多的特性，要想全部掌握它們很困難。然而，花費更多的時間在命令列編輯器上總是有幫助的。毫無疑問，和 Vim 用户們進行交流能夠讓你更快地學習新穎有創造性的東西。</p><p><strong>注：</strong> 本文中用到的例子，使用的 Vim 版本是 7.4.52 。</p><h3 id="_1、-同時編輯多個文件" tabindex="-1">1、 同時編輯多個文件 <a class="header-anchor" href="#_1、-同時編輯多個文件" aria-label="Permalink to “1、 同時編輯多個文件”">​</a></h3><p>如果你是一名軟件開發者或者把 Vim 作為主要的編輯器，那麼可能很多時候你需要同時編輯多個文件。“緊跟（following）”是在同時編輯多個文件時可用的實用技巧。</p><p>不需要在多個 shell 界面中打開多個文件，你可以通過把多個文件的文件名作為 Vim 命令的參數從而在一個 shell 界面中打開多個文件。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vim 文件1 文件2 文件3</span></span></code></pre></div><p>第一個文件（例子中的文件1）將成為當前文件並被讀入緩衝區。</p><p>在編輯器中，使用 <code>:next</code> 或 <code>:n</code> 命令來移動到下一個文件，使用 <code>:prev</code> 或 <code>:N</code> 命令返回上一個文件。如果想直接切換到第一個文件或最後一個文件，使用 <code>:bf</code> 和 <code>:bl</code> 命令。特別地，如果想打開另外的文件並編輯，使用 <code>:e</code> 命令並把文件名作為參數（如果該文件不在當前目錄中則需要完整路徑做為參數）。</p><p>任何時候如果需要列出當前打開的所有文件，使用 <code>:ls</code> 命令。看下面展示的屏幕截圖。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-ls.png" alt="vim-ls" title="vim-ls"></p><p>注意 ”%a” 表示文件在當前活動窗口，而 “#” 表示上一個活動窗口的文件。</p><h3 id="_2、-通過自動補全節約時間" tabindex="-1">2、 通過自動補全節約時間 <a class="header-anchor" href="#_2、-通過自動補全節約時間" aria-label="Permalink to “2、 通過自動補全節約時間”">​</a></h3><p>想節約時間並提高效率嗎？使用縮寫吧。使用它們能夠快速寫出文件中多次出現、複雜冗長的詞。在 Vim 中縮寫命令寫就是 <code>ab</code> 。</p><p>比如，當你運行下面的命令以後：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:ab asap as soon as possible</span></span></code></pre></div><p>文件中出現的每一個 <code>asap</code> 都會被自動替換為 <code>as soon as possible</code> ，就像你自己輸入的一樣。</p><p>類似地，你可以使用縮寫來更正常見的輸入錯誤。比如，下面的命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:ab recieve receive</span></span></code></pre></div><p>將會自動更正拼寫錯誤，就像你自己輸入的一樣。如果在一次特殊情況下你想阻止縮寫展開或更正發生，那麼你只需要在輸入一個單詞的最後一個字母以後按 <code>Ctrl + V</code> ，然後按空格鍵。</p><p>如果你想把剛才使用的縮寫保存下來，從而當你下次使用 Vim 編輯器的時候可以再次使用，那麼只需將完整的 <code>ab</code> 命令(沒有起始的冒號)添加到　<code>/etc/vim/vimrc</code> 文件中。如果想刪除某個縮寫，你可以使用 <code>una</code> 命令。比如： <code>una asap</code> 。</p><h3 id="_3、-切分窗口便於複製-粘貼" tabindex="-1">3、 切分窗口便於複製/粘貼 <a class="header-anchor" href="#_3、-切分窗口便於複製-粘貼" aria-label="Permalink to “3、 切分窗口便於複製/粘貼”">​</a></h3><p>有時，你需要從一個文件將一段代碼或文本的一部分複製到另一個。當使用 GUI（圖形界面）編輯器的時候，這很容易實現，但是當使用一個命令列編輯器的時候，這就變得比較困難並且很費時間。幸運的是， Vim 提供了一種高效、節約時間的方式來完成這件事。</p><p>打開兩個文件中的一個然後切分 Vim 窗口來打開另一個文件。可以通過使用 <code>split</code> 命令並以文件名作為參數來完成這件事。比如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:split test.c</span></span></code></pre></div><p>上面的命令將分離窗口並打開文件 “test.c”</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-split.png" alt="vim-split" title="vim-split"></p><p>注意到 <code>split</code> 命令水平分離 Vim 窗口。如果你想垂直分離窗口，那麼你可以使用 <code>vsplit</code> 命令。當同時打開了兩個文件並從一個文件中複製好內容以後，按 <code>Ctrl + W</code> 切換到另一個文件，然後粘貼。</p><h3 id="_4、-保存一個沒有權限的已編輯文件" tabindex="-1">4、 保存一個沒有權限的已編輯文件 <a class="header-anchor" href="#_4、-保存一個沒有權限的已編輯文件" aria-label="Permalink to “4、 保存一個沒有權限的已編輯文件”">​</a></h3><p>有時候當你對一個文件做了大量更改以後才會意識到你對該文件僅有 <code>只讀</code> 權限。</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-sudo.png" alt="vim-sudo" title="vim-sudo"></p><p>雖然把文件關閉，獲取權限以後再重新打開是一種解決方法。但是如果你已經做了大量更改，這樣做會很浪費時間，因為在這個過程中所有的更改都會丟失。 Vim 提供了一種方式來處理這種情況：你可以在編輯器中在保存文件前更改文件權限。命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:w !sudo tee %</span></span></code></pre></div><p>這個命令將會向你詢問密碼，就像在命令列中使用 <code>sudo</code> 一樣，然後就能保存更改。</p><p><strong>一個相關的技巧</strong>：在 Vim 中編輯一個文件的時候，如果想快速進入命令列提示符，可以在編輯器中運行 <code>:sh</code> 命令，從而你將進入一個交互的 shell 中。完成以後，運行 <code>exit</code> 命令可以快速回到 Vim 模式中。</p><h3 id="_5、-在複製-粘貼過程中保持縮進" tabindex="-1">5、 在複製/粘貼過程中保持縮進 <a class="header-anchor" href="#_5、-在複製-粘貼過程中保持縮進" aria-label="Permalink to “5、 在複製/粘貼過程中保持縮進”">​</a></h3><p>大多數有經驗的程序員在 Vim 上工作時都會啓用自動縮進。雖然這是一個節約時間的做法，但是在粘貼一段已經縮進了的代碼的時候會產生新的問題。比如，下圖是我把一段已縮進代碼粘貼到一個在自動縮進的 Vim 編輯器中打開的文件中時遇到的問題：</p><p><img src="https://maketecheasier-2d0f.kxcdn.com/assets/uploads/2014/08/vim-indentation.png" alt="vim-indentation" title="vim-indentation"></p><p>這個問題的解決方法是 <code>pastetoggle</code> 選項。在 <code>/etc/vim/vimrc</code> 文件中加入下面這行內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>set pastetoggle=&lt;F2&gt;</span></span></code></pre></div><p>然後當你在 <code>插入</code> 模式中準備粘貼代碼前先按 <code>F2</code> 鍵，就不會再出現上圖中的問題，這樣會保留原始的縮進。注意，你可以用其他的任何鍵來代替 <code>F2</code>，如果它已經映射到了別的功能上。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>更進一步的提高你的 Vim 編輯器技巧的唯一方法是，在你日復一日的工作中使用命令列編輯器。留意那些耗時多的操作，然後嘗試去尋找是否有編輯器命令可以很快地完成這個操作。</p><hr>',43)),i("p",null,[e[8]||(e[8]=s("via: ",-1)),a(t,{href:"https://www.maketecheasier.com/vim-tips-tricks-for-experienced-users/"},{default:l(()=>[...e[7]||(e[7]=[s("https://www.maketecheasier.com/vim-tips-tricks-for-experienced-users/",-1)])]),_:1})]),i("p",null,[e[12]||(e[12]=s("作者：",-1)),a(t,{href:"https://www.maketecheasier.com/author/himanshu/"},{default:l(()=>[...e[9]||(e[9]=[s("Himanshu Arora",-1)])]),_:1}),e[13]||(e[13]=s(" 譯者：",-1)),a(t,{href:"https://github.com/ucasFL"},{default:l(()=>[...e[10]||(e[10]=[s("ucasFL",-1)])]),_:1}),e[14]||(e[14]=s(" 校對：",-1)),a(t,{href:"https://github.com/wxy"},{default:l(()=>[...e[11]||(e[11]=[s("wxy",-1)])]),_:1})]),i("p",null,[e[17]||(e[17]=s("本文由 ",-1)),a(t,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...e[15]||(e[15]=[s("LCTT",-1)])]),_:1}),e[18]||(e[18]=s(" 原創編譯，",-1)),a(t,{href:"https://linux.cn/"},{default:l(()=>[...e[16]||(e[16]=[s("Linux中國",-1)])]),_:1}),e[19]||(e[19]=s(" 榮譽推出",-1))])])}const V=d(m,[["render",c]]);export{x as __pageData,V as default};
